      // Determinism: calling with same inputs should yield the same output
      int[] intArray1Again = MaxMin2.maxMin2(intArray0, 0);
      assertArrayEquals("Result should be deterministic for the same input", intArray1, intArray1Again);

      // Each element should either be a valid index into the source array or a value
